<?php require_once 'config/config.php'; if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$pass=$_POST['password']??'';if(!$email||strlen($pass)<8)$err='Valid email and 8+ character password required';else{try{$s=db()->prepare('INSERT INTO users(email,password_hash) VALUES(?,?)');$s->execute([$email,password_hash($pass,PASSWORD_DEFAULT)]);header('Location: login.php');exit;}catch(Exception $e){$err='Email already registered';}}} require 'includes/header.php';?><div class=card><h1>Create account</h1><?php if(isset($err)):?><p class=danger><?=e($err)?></p><?php endif;?><form method=post><input type=hidden name=csrf value="<?=csrf()?>"><input name=email type=email placeholder=Email required><input name=password type=password placeholder="Password (8+ chars)" required><button>Sign up</button></form></div><?php require 'includes/footer.php';?>
